Vim allows to access environment variable, register, and option with `let` like

```
" :help :let-$
let ${env-name} = {expr}

" :help :let-@
let @{reg-name} = {expr}

" :help :let-&amp;
let &amp;{option-name} = {expr}
let &amp;l:{option-name} = {expr}
let &amp;g:{option-name} = {expr}
```

thus add the following accessors to support above

☐ `environment` (alias to `e`)
☐ `register` (alias to `r`)
☐ `option` (alias to `o`)
☐ `localOption` (alias to `lo`)
☐ `globalOption` (alias to `go`)

```
import { assertEquals, assertThrowsAsync } from "../deps_test.ts";
import { test } from "../deps_test.ts";
import * as anonymous from "./mod.ts";

test({
  mode: "all",
  name: "add() registers anonymous functions",
  fn: async (denops) =&gt; {
    const ids = anonymous.add(
      denops,
      () =&gt; Promise.resolve("0"),
      () =&gt; Promise.resolve("1"),
      () =&gt; Promise.resolve("2"),
    );
    assertEquals(await denops.dispatch(denops.name, ids[0]), "0");
    assertEquals(await denops.dispatch(denops.name, ids[1]), "1");
    assertEquals(await denops.dispatch(denops.name, ids[2]), "2");
    assertEquals(await denops.dispatch(denops.name, ids[0]), "0");
    assertEquals(await denops.dispatch(denops.name, ids[1]), "1");
    assertEquals(await denops.dispatch(denops.name, ids[2]), "2");
  },
});

test({
  mode: "all",
  name: "once() registers oneshot anonymous functions",
  fn: async (denops) =&gt; {
    const ids = anonymous.once(
      denops,
      () =&gt; Promise.resolve("0"),
      () =&gt; Promise.resolve("1"),
      () =&gt; Promise.resolve("2"),
    );
    assertEquals(await denops.dispatch(denops.name, ids[0]), "0");
    assertEquals(await denops.dispatch(denops.name, ids[1]), "1");
    assertEquals(await denops.dispatch(denops.name, ids[2]), "2");

    // The method will be removed
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[0]);
      },
      undefined,
      `No method '${ids[0]}' exists`,
    );
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[1]);
      },
      undefined,
      `No method '${ids[1]}' exists`,
    );
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[2]);
      },
      undefined,
      `No method '${ids[2]}' exists`,
    );
  },
});

test({
  mode: "all",
  name: "remove() unregisters anonymous functions identified by ids",
  fn: async (denops) =&gt; {
    const ids = anonymous.add(
      denops,
      () =&gt; Promise.resolve("0"),
      () =&gt; Promise.resolve("1"),
      () =&gt; Promise.resolve("2"),
    );
    assertEquals(anonymous.remove(denops, ...ids), [true, true, true]);

    // The method is removed
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[0]);
      },
      undefined,
      `No method '${ids[0]}' exists`,
    );
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[1]);
      },
      undefined,
      `No method '${ids[1]}' exists`,
    );
    await assertThrowsAsync(
      async () =&gt; {
        await denops.dispatch(denops.name, ids[2]);
      },
      undefined,
      `No method '${ids[2]}' exists`,
    );
  },
});

```

Like

```
import * as option from "denops_std/option";

export async function main(denops) {
  console.log(await option.autoread.get(denops));
  console.log(await option.autoread.getLocal(denops));
  console.log(await option.autoread.getGlobal(denops));

  await option.autoread.set(denops, {value});
  await option.autoread.setLocal(denops, {value});
  await option.autoread.setGlobal(denops, {value});

  await option.autoread.reset(denops);

  await option.autoread.invert(denops); // may exist for boolean option
  await option.autoread.on(denops); // may exist for boolean option
  await option.autoread.off(denops); // may exist for boolean option
}
```

